namespace NC069_LRUCache;

public class SolutionTests
{
    [Fact]
    public void Example1()
    {
        var c = new LRUCache(2);
        c.Put(1, 1);
        c.Put(2, 2);
        Assert.Equal(1, c.Get(1));
        c.Put(3, 3); // evicts 2
        Assert.Equal(-1, c.Get(2));
        c.Put(4, 4); // evicts 1
        Assert.Equal(-1, c.Get(1));
        Assert.Equal(3, c.Get(3));
        Assert.Equal(4, c.Get(4));
    }
    [Fact]
    public void UpdateRefreshesRecency()
    {
        var c = new LRUCache(2);
        c.Put(1, 1);
        c.Put(2, 2);
        c.Put(1, 10); // update makes 1 most recent
        c.Put(3, 3);  // evicts 2
        Assert.Equal(-1, c.Get(2));
        Assert.Equal(10, c.Get(1));
        Assert.Equal(3, c.Get(3));
    }
    [Fact]
    public void CapacityOne()
    {
        var c = new LRUCache(1);
        c.Put(2, 1);
        Assert.Equal(1, c.Get(2));
        c.Put(3, 2);
        Assert.Equal(-1, c.Get(2));
        Assert.Equal(2, c.Get(3));
    }
}